.sidebar {
  container: sidebar / inline-size;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  height: 100%;
  background: #f5f6f9;
  border-right: 1px solid #dfe3ea;
  padding: 1rem 0.75rem;
  box-sizing: border-box;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.switcherLabel {
  display: block;
}

.switcherSelect {
  width: 100%;
  border: 1px solid #c9cfdb;
  border-radius: 0.375rem;
  background: #fff;
  padding: 0.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: #1f2a44;
}

.nav {
  list-style: none;
  margin: 0;
  padding: 0;
